import numpy as np

# Illustrative weights: a product decision, tuned by A/B tests on long-term metrics
W = {"like": 1.0, "comment": 4.0, "share": 6.0, "dwell_min": 0.5, "hide": -40.0}

def value(p: dict[str, np.ndarray]) -> np.ndarray:
    # Every head must be calibrated, or "a comment is worth 4 likes" means nothing
    return sum(w * p[k] for k, w in W.items())

def final_pass(items: list[dict], v: np.ndarray, n: int = 25, decay: float = 0.6) -> list[dict]:
    v = v * (1 - np.array([it["integrity_demotion"] for it in items]))  # 0 = none, 1 = remove
    left = v > 0                     # negative expected value: never show
    feed, per_author = [], {}
    for _ in range(min(n, int(left.sum()))):
        # Re-score what is left given what is already on the page
        adj = np.array([v[i] * decay ** per_author.get(it["author"], 0) for i, it in enumerate(items)])
        i = int(np.argmax(np.where(left, adj, -np.inf)))
        left[i] = False
        feed.append(items[i])
        per_author[items[i]["author"]] = per_author.get(items[i]["author"], 0) + 1
    return feed

